// Match the SVG viewport to the available screen without stretching geography.
// A tall viewport shows a closer view; dragging reaches the other continents.
let mapView={width:1000,height:490};
function fitMapViewport(){const rect=$('map').getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=rect.width/rect.height;mapView=ratio<1000/490?{width:490*ratio,height:490}:{width:1000,height:1000/ratio};$('map').setAttribute('viewBox',`${500-mapView.width/2} ${245-mapView.height/2} ${mapView.width} ${mapView.height}`);const stats=root.querySelector('.stats').getBoundingClientRect();const mapRect=root.querySelector('.mapwrap').getBoundingClientRect();workspace.style.setProperty('--controls-bottom',Math.max(90,mapRect.bottom-stats.top+12)+'px')}
new ResizeObserver(fitMapViewport).observe(root.querySelector('.mapwrap'));new ResizeObserver(fitMapViewport).observe(root.querySelector('.stats'));fitMapViewport();

